type jsRegExp struct {
	Source, Flags jsString
	compiled      *regexp.Regexp
	denied        *regexp.Regexp
	LastIndex     int32
}

var macroPlaceholderPattern = regexp.MustCompile("^&[1-9][0-9]*$")
var literalAlternativePattern = regexp.MustCompile("^\\^[A-Za-z0-9_|()?]+\\$?$")

func newRegExp(pattern, flags jsString) *jsRegExp {
	p, f := pattern.String(), flags.String()
	spec, ok := reviewedRegexPatterns[p+"/"+f]
	if !ok && f == "g" && macroPlaceholderPattern.MatchString(p) {
		spec = [2]string{p, ""}
		ok = true
	}
	if !ok && (f == "" || f == "i") && literalAlternativePattern.MatchString(p) {
		translated := p
		if f == "i" {
			var out strings.Builder
			for _, c := range p {
				if c >= 'a' && c <= 'z' || c >= 'A' && c <= 'Z' {
					out.WriteRune('[')
					out.WriteRune(unicode.ToUpper(c))
					out.WriteRune(unicode.ToLower(c))
					out.WriteRune(']')
				} else {
					out.WriteRune(c)
				}
			}
			translated = out.String()
		}
		spec = [2]string{translated, ""}
		ok = true
	}
	if !ok {
		if translated, accepted := TranslateSubset(p, f); accepted {
			spec = [2]string{translated, ""}
			ok = true
		}
	}
	if !ok {
		panic(newTrap("unreviewed JavaScript regexp /" + p + "/" + f))
	}
	var denied *regexp.Regexp
	if spec[1] != "" {
		denied = regexp.MustCompile(spec[1])
	}
	source := pattern.replaceAll(str("/"), str("\\/"))
	if pattern == "" {
		source = str("(?:)")
	}
	return &jsRegExp{Source: source, Flags: flags, compiled: compileCheckedRegexp(spec[0], p, f), denied: denied}

}
func compileCheckedRegexp(translated, pattern, flags string) *regexp.Regexp {
	r, err := regexp.Compile(translated)
	if err != nil {
		panic(newTrap("invalid checked JavaScript regexp /" + pattern + "/" + flags + ": " + err.Error()))
	}
	return r
}
func unitText(s jsString) string {
	var b strings.Builder
	for i := int32(0); i < s.length(); i++ {
		b.WriteRune(rune(s.charCodeAt(i)))
	}
	return b.String()
}
