	matches := r.compiled.FindAllStringIndex(input, -1)
	if len(matches) == 0 {
		return nil
	}
	out := &array[jsString]{}
	for _, m := range matches {
		a := int32(utf8.RuneCountInString(input[:m[0]]))
		b := int32(utf8.RuneCountInString(input[:m[1]]))
		out.Items = append(out.Items, s[2*a:2*b])
	}
