func (p *json5Parser) value() *dynamic {
	p.space()
	switch p.peek() {
	case 34, 39:
		return box(p.text())
	case 110:
		p.literal("null")
		return dynNull()
	case 116:
		p.literal("true")
		return box(true)
	case 102:
		p.literal("false")
		return box(false)
	case 123, 91:
		arrayMode := p.read() == 91
		close := int32(125)
		if arrayMode {
			close = 93
		}
		d := &dynamic{Tag: tagObject, Value: &orderedMap[jsString, *dynamic]{}}
		a := &array[any]{}
		if arrayMode {
			d = &dynamic{tagArray, a}
		}
		p.space()
		if p.peek() == close {
			p.read()
			return d
		}
		for {
			if arrayMode {
				a.push(p.value())
			} else {
				p.space()
				k := p.key()
				p.space()
				p.take(58)
				d.put(k, p.value())
			}
			p.space()
			if p.peek() == close {
				p.read()
				return d
			}
			p.take(44)
			p.space()
			if p.peek() == close {
				p.read()
				return d
			}
		}
	default:
		return p.number()
	}
}
func parseJSON5(input jsString, onSyntaxError func(jsString)) *dynamic {
	p := &json5Parser{input: input, line: 1, onSyntaxError: onSyntaxError}
	d := p.value()
	p.space()
	if p.peek() != -1 {
		p.invalid()
	}
	if p.nonfinite {
		panic(newTrap("JSON5 nonfinite Number representation is unsupported"))
	}
	return d
}

