// Usage-gated JSON data-graph writer; native own-key order must be proven.
type configJSONWriter struct{ active map[any]bool }

func (w *configJSONWriter) enter(v any) {
	if w.active[v] {
		panic(newTrap("cyclic config JSON graph"))
	}
	w.active[v] = true
}
func (w *configJSONWriter) leave(v any) { delete(w.active, v) }

// A supplied native version object has no retained literal key order. Only
// the function's freshly built version literal or a tagged JSON input is proven.
func stringifyConfigChecked(v any, ver *dynamic, lang optional[jsString]) jsString {
	if !lang.Has && ver != nil && ver.Tag == 2 {
		if native, ok := ver.Value.(interface{ dynamicSource() *dynamic }); ok && native.dynamicSource() == nil {
			panic(newTrap("config JSON native version input own-key order is unproven"))
		}
	}
	return stringifyConfig(v)
}
func stringifyConfig(v any) jsString {
	w := &configJSONWriter{active: map[any]bool{}}
	s, ok := w.value(v)
	if !ok {
		panic(newTrap("undefined config JSON root"))
	}
	return s
}
func (v optional[T]) configJSONOptional() (any, bool) { return v.Value, v.Has }
func (a *array[T]) configJSON(w *configJSONWriter) jsString {
	if a == nil {
		return str("null")
	}
	w.enter(a)
	defer w.leave(a)
	out := str("[")
	for i := range a.values() {
		if i > 0 {
			out += str(",")
		}
		s, ok := w.value(a.get(int32(i)))
		if !ok {
			s = str("null")
		}
		out += s
	}
	return out + str("]")
}
func (m *orderedMap[K, V]) configJSON(w *configJSONWriter) jsString {
	if m == nil {
		return str("null")
	}
	w.enter(m)
	defer w.leave(m)
	entries := []entry[jsString, any]{}
	for _, e := range m.Entries {
		k, ok := any(e.Key).(jsString)
		if !ok {
			panic(newTrap("config JSON requires string record keys"))
		}
		entries = append(entries, entry[jsString, any]{k, e.Value})
	}
	return w.object(entries)
}
func jsonIndex(k jsString) (uint64, bool) {
	s := k.String()
	n, err := strconv.ParseUint(s, 10, 32)
	return n, err == nil && n < 4294967295 && strconv.FormatUint(n, 10) == s
}
func (w *configJSONWriter) object(entries []entry[jsString, any]) jsString {
	// ES own-key ordering: canonical array indices first, other strings in insertion order.
	indexed := []entry[jsString, any]{}
	rest := []entry[jsString, any]{}
	for _, e := range entries {
		if _, ok := jsonIndex(e.Key); ok {
			indexed = append(indexed, e)
		} else {
			rest = append(rest, e)
		}
	}
	for i := 1; i < len(indexed); i++ {
		for j := i; j > 0; j-- {
			a, _ := jsonIndex(indexed[j-1].Key)
			b, _ := jsonIndex(indexed[j].Key)
			if a <= b {
				break
			}
			indexed[j-1], indexed[j] = indexed[j], indexed[j-1]
		}
	}
	out := str("{")
	comma := false
	for _, e := range append(indexed, rest...) {
		s, ok := w.value(e.Value)
		if !ok {
			continue
		}
		if comma {
			out += str(",")
		}
		comma = true
		out += jsonQuote(e.Key) + str(":") + s
	}
	return out + str("}")
}
func (w *configJSONWriter) value(v any) (jsString, bool) {
	if o, ok := v.(interface{ configJSONOptional() (any, bool) }); ok {
		value, has := o.configJSONOptional()
		if !has {
			return "", false
		}
		return w.value(value)
	}
	if nilRef(v) {
		return "", false
	}
	switch x := v.(type) {
	case jsString:
		return jsonQuote(x), true
	case bool:
		return str(strconv.FormatBool(x)), true
	case int32:
		return str(strconv.FormatInt(int64(x), 10)), true
	case int64:
		if x > 9007199254740991 || x < -9007199254740991 {
			panic(newTrap("config JSON integer outside JS safe domain"))
		}
		return str(strconv.FormatInt(x, 10)), true
	case float64:
		return jsonNumber(x), true
	case *dynamic:
		if x.Tag == tagNull {
			return str("null"), true
		}
		if x.Tag == 10 {
			return "", false
		}
		return w.value(x.Value)
	}
	if s, ok := v.(interface {
		configJSON(*configJSONWriter) jsString
	}); ok {
		return s.configJSON(w), true
	}
	if s, ok := v.(interface{ dynamicSource() *dynamic }); ok {
		if d := s.dynamicSource(); d != nil {
			return w.value(d)
		}
	}
	panic(newTrap("unsupported config JSON value"))
}
func jsonNumber(n float64) jsString {
	if math.IsNaN(n) || math.IsInf(n, 0) {
		return str("null")
	}
	if n == 0 {
		return str("0")
	}
	format := byte('f')
	a := math.Abs(n)
	if a < 1e-6 || a >= 1e21 {
		format = 'e'
	}
	s := strconv.FormatFloat(n, format, -1, 64)
	if at := strings.IndexByte(s, 'e'); at >= 0 {
		exponent, _ := strconv.Atoi(s[at+1:])
		sign := ""
		if exponent >= 0 {
			sign = "+"
		}
		s = s[:at+1] + sign + strconv.Itoa(exponent)
	}
	return str(s)
}
func jsonQuote(s jsString) jsString {
	out := str("\"")
	hex := "0123456789abcdef"
	for i := int32(0); i < s.length(); i++ {
		c := s.charCodeAt(i)
		switch c {
		case 34:
			out += str("\\\"")
		case 92:
			out += str("\\\\")
		case 8:
			out += str("\\b")
		case 9:
			out += str("\\t")
		case 10:
			out += str("\\n")
		case 12:
			out += str("\\f")
		case 13:
			out += str("\\r")
		default:
			lone := c >= 0xd800 && c <= 0xdfff
			if c >= 0xd800 && c <= 0xdbff && i+1 < s.length() {
				d := s.charCodeAt(i + 1)
				if d >= 0xdc00 && d <= 0xdfff {
					out += unit(c) + unit(d)
					i++
					continue
				}
			}
			if c < 32 || lone {
				out += str("\\u" + string([]byte{hex[(c>>12)&15], hex[(c>>8)&15], hex[(c>>4)&15], hex[c&15]}))
			} else {
				out += unit(c)
			}
		}
	}
	return out + str("\"")
}
